import{_ as o,C as n,o as i,c as r,j as a,a as s,E as c,al as l}from"./chunks/framework.7vp1BMOE.js";const v=JSON.parse('{"title":"Gain compression","description":"","frontmatter":{},"headers":[],"relativePath":"en/features_mc/gain_compression.md","filePath":"en/features_mc/gain_compression.md"}'),d={name:"en/features_mc/gain_compression.md"};function h(p,e,m,_,u,f){const t=n("Badge");return i(),r("div",null,[e[0]||(e[0]=a("h1",{id:"gain-compression",tabindex:"-1"},[s("Gain compression "),a("a",{class:"header-anchor",href:"#gain-compression","aria-label":'Permalink to "Gain compression"'},"​")],-1)),c(t,{type:"tip",text:"PX4 v2.0"}),e[1]||(e[1]=l('<p>Automatic gain compression reduces the gains of the angular-rate PID whenever oscillations are detected. It monitors the angular-rate controller output (the torque setpoint) through a band-pass filter to identify these oscillations, and scales the output down until they stop. The gain recovers to 1.0 once the oscillation is gone.</p><p>This approach is a safe adaptive mechanism: the PID gains remain unchanged when no oscillations are present, they are never increased beyond their nominal values, and they are bounded by a minimum limit (<a href="./../advanced_config/parameter_reference#MC_GC_GAIN_MIN">MC_GC_GAIN_MIN</a>).</p><p>Gain compression can help prevent actuator damage, and even loss of the vehicle, when the rate loop becomes oscillatory in flight: for example after a payload change that shifts the CG or inertia, a partial propeller failure, or gains that were tuned for a different configuration. It removes the need to retune manually for the oscillation to stop.</p><p>The algorithm is the same one used on fixed-wing vehicles, where you can also find a <a href="./../features_fw/gain_compression">block diagram</a> of the adaptive law (the multicopter rate loop has no airspeed scaling stage).</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><p>Gain compression is disabled by default and is enabled with <a href="./../advanced_config/parameter_reference#MC_GC_EN">MC_GC_EN</a>.</p><p>It should be disabled during multicopter <a href="./../config_mc/pid_tuning_guide_multicopter">manual tuning</a> to avoid over-tuning: with compression active, an oscillation caused by gains that are too high is damped out, which hides the very symptom the tuning process relies on. It does not need to be disabled when <a href="./../config/autotune_mc">autotuning</a>.</p><p>Compression is automatically reset (gain back to 1.0) while the vehicle is disarmed or landed, so that vibration from ground contact cannot compress the gains before takeoff.</p><h2 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h2><ul><li><a href="./../advanced_config/parameter_reference#MC_GC_EN">MC_GC_EN</a></li><li><a href="./../advanced_config/parameter_reference#MC_GC_GAIN_MIN">MC_GC_GAIN_MIN</a></li></ul>',10))])}const b=o(d,[["render",h]]);export{v as __pageData,b as default};
